// A web server that switches the LEDs from a browser
#include <ESP8266WiFi.h>
#include <ESP8266WebServer.h>

const char* ssid = "{{p:ssid}}";
const char* password = "";       // this network has no password
const int LED_PIN = D1;

ESP8266WebServer server(80);

void handleRoot() {
  server.send(200, "text/plain", "NodeMCU: try /on or /off");
}

void handleOn() {
  digitalWrite(LED_PIN, HIGH);
  digitalWrite(LED_BUILTIN, LOW);  // LOW lights the blue LED
  server.send(200, "text/plain", "LED on");
}

void handleOff() {
  digitalWrite(LED_PIN, LOW);
  digitalWrite(LED_BUILTIN, HIGH);
  server.send(200, "text/plain", "LED off");
}

void setup() {
  Serial.begin(115200);
  pinMode(LED_PIN, OUTPUT);
  pinMode(LED_BUILTIN, OUTPUT);
  digitalWrite(LED_BUILTIN, HIGH);
  WiFi.mode(WIFI_STA);             // station mode: join a network as a client
  WiFi.begin(ssid, password);
  Serial.print("Connecting");
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);                    // connecting takes about a second
    Serial.print(".");
  }
  Serial.println();
  Serial.print("IP address: ");
  Serial.println(WiFi.localIP());
  server.on("/", handleRoot);
  server.on("/on", handleOn);
  server.on("/off", handleOff);
  server.begin();
  Serial.println("HTTP server started");
}

void loop() {
  server.handleClient();           // answer browser requests all the time
}

